    private static DeferredBlock<Block> block(String id, Supplier<Block> b) {
        DeferredBlock<Block> h = ModBlocks.BLOCKS.register(id, b);
        ModItems.ITEMS.registerSimpleBlockItem(h);
        ALL_MUTABLE.add(h);
        return h;
    }

